import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 210;
    static final int INF = Integer.MAX_VALUE;
    static int[][] cap = new int[MAXN][MAXN];
    static int[][] flow = new int[MAXN][MAXN];
    static int[][] g = new int[MAXN][MAXN];
    static int n, t, source, sink;
    static int[] h = new int[MAXN];
    static int[] vh = new int[MAXN];
    static int[] mk = new int[MAXN];
    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {-1, 1, 0, 0};
    static String[] mat1 = new String[MAXN];
    static String[] mat2 = new String[MAXN];
    static int[][] flag = new int[MAXN][MAXN];
    static int[][] vis = new int[MAXN][MAXN];

    // Helper class for Nodes
    static class Node {
        int x, y, step;
        public Node(int x, int y, int step) {
            this.x = x;
            this.y = y;
            this.step = step;
        }
    }

    // Indices computing
    static int ID(int i, int j) {
        return (i - 1) * n + j;
    }

    // Check validity
    static boolean check(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= n;
    }

    // BFS1: find distances from starting point sx, sy
    static void BFS1() {
        Queue<Node> Q = new LinkedList<>();
        Node now, next;
        now = new Node(sx, sy, 0);
        Q.offer(now);
        for (int[] row : flag) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        for (int[] row : vis) {
            Arrays.fill(row, 0);
        }
        vis[sx][sy] = 1;
        while (!Q.isEmpty()) {
            now = Q.poll();
            flag[now.x][now.y] = now.step;
            if (now.step > t) break;
            for (int k = 0; k < 4; k++) {
                int x = now.x + dx[k], y = now.y + dy[k];
                if (check(x, y) && mat1[x - 1].charAt(y - 1) != 'Y' && vis[x][y] == 0) {
                    next = new Node(x, y, now.step + 1);
                    vis[x][y] = 1;
                    Q.offer(next);
                }
            }
        }
    }

    // BFS2: find reachable nodes
    static void BFS2(int i, int j) {
        Queue<Node> Q = new LinkedList<>();
        Node now, next;
        now = new Node(i, j, 0);
        for (int[] row : vis) {
            Arrays.fill(row, 0);
        }
        vis[i][j] = 1;
        Q.offer(now);
        while (!Q.isEmpty()) {
            now = Q.poll();
            if (now.step > t) break;
            if (flag[now.x][now.y] < now.step) continue;
            if ((flag[now.x][now.y] == now.step && mat2[now.x - 1].charAt(now.y - 1) < '1') || mat2[now.x - 1].charAt(now.y - 1) > '9') continue;
            if (mat2[now.x - 1].charAt(now.y - 1) >= '1' && mat2[now.x - 1].charAt(now.y - 1) <= '9') {
                if (now.x != i || now.y != j) {
                    addCap(ID(i, j), ID(now.x, now.y) + n * n, INF);
                }
                if (flag[now.x][now.y] == now.step) continue;
            }
            for (int k = 0; k < 4; k++) {
                int x = now.x + dx[k], y = now.y + dy[k];
                if (check(x, y) && mat1[x - 1].charAt(y - 1) != 'Y' && vis[x][y] == 0) {
                    next = new Node(x, y, now.step + 1);
                    vis[x][y] = 1;
                    Q.offer(next);
                }
            }
        }
    }

    // Implementation of SAP algorithm
    static int sap(int idx, int maxCap) {
        if (idx == sink)
            return maxCap;
        int l = maxCap, d, minH = n;
        for (int i = 0; i <= sink; i++) {
            if (cap[idx][i] - flow[idx][i] > 0) {
                if (h[idx] == h[i] + 1) {
                    d = sap(i, Math.min(l, cap[idx][i] - flow[idx][i]));
                    flow[idx][i] += d;
                    flow[i][idx] -= d;
                    l -= d;
                    if (h[source] == n || l == 0) return maxCap - l;
                }
                minH = Math.min(minH, h[i] + 1);
            }
        }
        if (l == maxCap) {
            vh[h[idx]]--;
            if (vh[h[idx]] < 0) {
                // Should not happen in valid flow
                vh[h[idx]] = 0;
            }
            h[idx] = minH;
            vh[h[idx]]++;
        }
        return maxCap - l;
    }

    static int solve(int src, int snk) {
        if (src == snk) return INF;
        source = src;
        sink = snk;
        for (int i = 0; i <= sink; i++) {
            for (int j = 0; j <= sink; j++) {
                flow[i][j] = 0;
            }
        }
        Arrays.fill(h,0);
        Arrays.fill(vh,0);
        int ans = 0;
        while (h[source] != n + 1) {
            ans += sap(source, INF);
        }
        return ans;
    }

    static void addCap(int i, int j, int val) {
        cap[i][j] += val;
        g[i][j] = 1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tk = new StringTokenizer(br.readLine());
        n = Integer.parseInt(tk.nextToken());
        t = Integer.parseInt(tk.nextToken());
        for (int i = 0; i < n; i++) {
            mat1[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            mat2[i] = br.readLine();
        }
        int sinkNode = 2 * n * n + 1;
        // Initialize arrays
        for (int[] row : cap) {
            Arrays.fill(row, 0);
        }

        int s = 0, snk = sinkNode;

        // Build graph
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                char c1 = mat1[i - 1].charAt(j - 1);
                if (c1 >= '1' && c1 <= '9') {
                    addCap(s, ID(i, j), c1 - '0');
                }
                if (c1 == 'Z') {
                    sx = i;
                    sy = j;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int id = ID(i, j);
                // node split
                addCap(id, id + n * n, INF);
                char c2 = mat2[i - 1].charAt(j - 1);
                if (c2 >= '1' && c2 <= '9') {
                    addCap(id + n * n, snk, c2 - '0');
                }
            }
        }

        BFS1();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (mat1[i -1].charAt(j -1) >= '1' && mat1[i -1].charAt(j -1) <= '9') {
                    BFS2(i, j);
                }
            }
        }

        int res = solve(s, snk);
        System.out.println(res);
    }
}

